// File: fcm_avalon_sva.sv
// Description: Avalon-MM slave protocol assertions for image_upload_avalon_slave.

// Check both the Avalon-MM master and slave protocol.
// The master must keep commands stable while waitrequest is high.
// The slave must return valid data and must not stall forever.
// These checks also catch bad traffic generated by the testbench.

// Module: fcm_avalon_mm_sva
// Description: Checks Avalon-MM slave protocol rules with assertions.
module fcm_avalon_mm_sva #(
    // Allow enough wait cycles for SDRAM backpressure.
    // This limit catches a stuck transfer, not a slow transfer.
    parameter int MAX_WAIT_CYCLES = 100000
)(
    input logic        clk,
    input logic        reset_n,
    input logic [2:0]  avs_address,
    input logic        avs_read,
    input logic        avs_write,
    input logic [31:0] avs_writedata,
    input logic [3:0]  avs_byteenable,
    input logic [31:0] avs_readdata,
    input logic        avs_waitrequest
);

  default clocking cb @(posedge clk); endclocking
  default disable iff (!reset_n);

  wire cmd = avs_read || avs_write;

  // Check the commands sent by the Avalon-MM master.

  // Do not read and write in the same Avalon-MM cycle.
  a_no_read_and_write: assert property (
      !(avs_read && avs_write)
  ) else $error("avalon: read va write cung len");

  // Keep the address, data and control signals stable while waitrequest is high.
  // Otherwise the slave may accept a different command.
  a_cmd_stable_while_waited: assert property (
      (cmd && avs_waitrequest) |=> $stable({avs_address, avs_read, avs_write, avs_byteenable})
  ) else $error("avalon: lenh doi khi dang bi waitrequest chan");

  a_writedata_stable_while_waited: assert property (
      (avs_write && avs_waitrequest) |=> $stable(avs_writedata)
  ) else $error("avalon: writedata doi khi dang bi waitrequest chan");

  // Keep the pending command asserted until the slave accepts it.
  a_cmd_not_dropped: assert property (
      (cmd && avs_waitrequest) |=> cmd
  ) else $error("avalon: lenh bi rut ve trong khi dang bi chan");

  // At least one byteenable bit must be set for a valid transfer.
  // Check it at the master before the slave reports a protocol error.
  a_byteenable_nonzero: assert property (
      cmd |-> (avs_byteenable != 4'h0)
  ) else $error("avalon: byteenable toan 0");

  // Check the response signals from the Avalon-MM slave.

  // Fail if waitrequest stays high for too many cycles.
  a_waitrequest_bounded: assert property (
      avs_waitrequest |-> ##[1:MAX_WAIT_CYCLES] !avs_waitrequest
  ) else $error("avalon: waitrequest len qua %0d chu ky", MAX_WAIT_CYCLES);

  // Check readdata when a read is accepted without waitrequest.
  // This slave drives read data with combinational logic.
  a_readdata_known: assert property (
      (avs_read && !avs_waitrequest) |-> !$isunknown(avs_readdata)
  ) else $error("avalon: readdata co X/Z khi master lay du lieu");

endmodule


// Keep bind inside a module because these files are compiled without -mfcu.
// The testbench must instantiate fcm_avalon_sva_bind to enable the checks.

// Module: fcm_avalon_sva_bind
// Description: Binds the Avalon-MM assertions onto the upload slave.
module fcm_avalon_sva_bind;

  bind image_upload_avalon_slave fcm_avalon_mm_sva u_sva (
      .clk(clk), .reset_n(reset_n),
      .avs_address(avs_address), .avs_read(avs_read), .avs_write(avs_write),
      .avs_writedata(avs_writedata), .avs_byteenable(avs_byteenable),
      .avs_readdata(avs_readdata), .avs_waitrequest(avs_waitrequest)
  );

endmodule
